	/** 
	 * jumpstart the process by instantiating2 Team
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		teamId = TeamService.getTeamInstance()
		.createTeam( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		TeamService.getTeamInstance()
				.createTeam( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.teamSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Team : " + successValue.getTeamId());
							  if (successValue.getTeamId().equals(teamId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfTeamList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Team test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on team consumed")
					);
			subscriber.teamSubscribe( teamId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Team : " + successValue.getTeamId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfTeamList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on team for teamId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Team. 
	 */
	protected Team read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Team" );

		Team entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Team with primary key" );
		msg.append( teamId );
		
		TeamFetchOneSummary fetchOneSummary = new TeamFetchOneSummary( teamId );

		try {
			entity = TeamService.getTeamInstance().getTeam( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Team " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Team.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Team." );

		StringBuilder msg = new StringBuilder( "Failed to update a Team : " );        
		Team entity = read();
		UpdateTeamCommand command = generateUpdateCommand();
		command.setTeamId(entity.getTeamId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Team." );

			// for use later on...
			teamId = entity.getTeamId();

			TeamService proxy = TeamService.getTeamInstance();  

			proxy.updateTeam( command ).get();

			LOGGER.info( "-- Successfully saved Team - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + teamId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Team.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Team." );

		Team entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Team with id " + teamId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Team with id " + teamId );

			throw e;
		}

		try{
			TeamService.getTeamInstance().delete( new DeleteTeamCommand( entity.getTeamId() ) ).get();
			LOGGER.info( "-- Successfully deleted Team with id " + teamId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Team with id " + teamId );

			throw e;
		}
	}

	/**
	 * get all Teams.
	 */
	protected List<Team> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Teams:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Team : " );        
		List<Team> collection  = new ArrayList<>();

		try {
			// call the static get method on the TeamService
			collection = TeamService.getTeamInstance().getAllTeam();
			assertNotNull( collection, "An Empty collection of Team was incorrectly returned.");
			
			// Now print out the values
			Team entity = null;            
			Iterator<Team> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getTeamId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

